namespace Npro.Infrastructure.Files;

/// <summary>
/// Step 18d: where attachment bytes live. Disk now (a folder outside the website); an S3 implementation can replace it
/// without other changes (set <c>Storage:Provider</c>). Keys are generated by nPro — never taken from user input.
/// </summary>
public interface IFileStore
{
    string Provider { get; }
    Task SaveAsync(string key, Stream content, CancellationToken ct = default);
    /// <summary>Null when the file is missing</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken ct = default);
    Task DeleteAsync(string key, CancellationToken ct = default);
    /// <summary>For the health check: can we write right now?</summary>
    Task<bool> IsWritableAsync(CancellationToken ct = default);
}

public sealed class DiskFileStore : IFileStore
{
    private readonly string root;

    public DiskFileStore(string root)
    {
        this.root = Path.GetFullPath(root);
        Directory.CreateDirectory(this.root);
    }

    public string Provider => "disk";

    /// <summary>Maps a key to a path inside the root (rejects anything that would escape it)</summary>
    private string PathOf(string key)
    {
        if (string.IsNullOrWhiteSpace(key) || key.Contains("..") || Path.IsPathRooted(key)) throw new ArgumentException("Invalid storage key");
        var full = Path.GetFullPath(Path.Combine(root, key.Replace('/', Path.DirectorySeparatorChar)));
        if (!full.StartsWith(root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)) throw new ArgumentException("Invalid storage key");
        return full;
    }

    public async Task SaveAsync(string key, Stream content, CancellationToken ct = default)
    {
        var path = PathOf(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        await using var file = new FileStream(path, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, useAsync: true);
        await content.CopyToAsync(file, ct);
    }

    public Task<Stream?> OpenReadAsync(string key, CancellationToken ct = default)
    {
        var path = PathOf(key);
        return Task.FromResult<Stream?>(File.Exists(path) ? new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true) : null);
    }

    public Task DeleteAsync(string key, CancellationToken ct = default)
    {
        var path = PathOf(key);
        if (File.Exists(path)) File.Delete(path);
        return Task.CompletedTask;
    }

    public async Task<bool> IsWritableAsync(CancellationToken ct = default)
    {
        try
        {
            var probe = Path.Combine(root, $".health-{Guid.NewGuid():N}");
            await File.WriteAllTextAsync(probe, "ok", ct);
            File.Delete(probe);
            return true;
        }
        catch
        {
            return false;
        }
    }
}
